package com.example.assets_management.security.auth;
import com.example.assets_management.employee.entity.Employee; import com.example.assets_management.employee.repository.EmployeeRepository; import com.example.assets_management.security.service.CustomUserDetailsService; import com.example.assets_management.security.service.JwtService; import lombok.RequiredArgsConstructor; import org.springframework.beans.factory.annotation.Value; import org.springframework.security.core.userdetails.UserDetails; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.time.Instant; import java.util.*;
@Service @RequiredArgsConstructor @Transactional public class RefreshTokenService { private final RefreshTokenRepository repo; private final EmployeeRepository users; private final CustomUserDetailsService details; private final JwtService jwt; @Value("${JWT_REFRESH_EXPIRATION_MS:604800000}") private long refreshMs;
 public String issue(Employee user){String raw=random();RefreshToken r=new RefreshToken();r.setUser(user);r.setTokenHash(hash(raw));r.setExpiresAt(Instant.now().plusMillis(refreshMs));repo.save(r);return raw;}
 public RefreshTokenRotation rotate(String raw){RefreshToken r=repo.findByTokenHash(hash(raw)).orElseThrow(()->new IllegalArgumentException("Invalid refresh token"));if(!r.isActive())throw new IllegalStateException("Refresh token expired or revoked");String next=random();r.setRevokedAt(Instant.now());r.setReplacedByHash(hash(next));RefreshToken n=new RefreshToken();n.setUser(r.getUser());n.setTokenHash(hash(next));n.setExpiresAt(Instant.now().plusMillis(refreshMs));repo.save(r);repo.save(n);return new RefreshTokenRotation(n,next);}
 public void revoke(String raw){repo.findByTokenHash(hash(raw)).ifPresent(r->{r.setRevokedAt(Instant.now());repo.save(r);});}
 public UserDetails details(Employee u){return details.loadUserByUsername(u.getEmail());}
 public record RefreshTokenRotation(RefreshToken token,String rawToken) {}
 private String random(){return UUID.randomUUID()+"."+UUID.randomUUID()+"."+UUID.randomUUID();} private String hash(String v){try{byte[] b=MessageDigest.getInstance("SHA-256").digest(v.getBytes(StandardCharsets.UTF_8));return HexFormat.of().formatHex(b);}catch(Exception e){throw new IllegalStateException(e);}}
}
